class Solution {
public:
    int findLatestStep(vector<int>& arr, int m) {
        int n = arr.size();
        if (n == m) return n;

        vector<int> length(n + 2, 0);
        int count_m = 0;
        int result = -1;

        for (int i = 0; i < n; i++) {
            int p = arr[i];
            int left_len = length[p - 1];
            int right_len = length[p + 1];
            int new_len = left_len + 1 + right_len;

            if (left_len == m) count_m--;
            if (right_len == m) count_m--;
            if (new_len == m) count_m++;

            length[p - left_len] = new_len;
            length[p + right_len] = new_len;

            if (count_m > 0) result = i + 1;
        }

        return result;
    }
};
